// Generated by `just generate` from `src/plugins/dotclaude/slices/decide/adapters/mod.ts`. Edit the source and run `just generate`.
// The mod handlers of the `decide` slice.
// `session.start` registers the tool at each start, with or without a key, so the fallback is reachable with no key.
// `tool.call` serves the tool: it tries Jev when the key is set, and the fallback model when Jev gives no answer.
// A second `tool.call` handler adds the pick of Jev to each `AskUserQuestion` question that facts decide.
//
// `claude plugin validate` follows `$` only into a function of one file,
// and each `$.env.get` call needs a literal name.
// For this reason, each function that touches `$` is here, and the rules are in `domain/` and in the adapters.

import type { EngineInterface, MatchedHook } from "claude-code";
import type { Handler } from "../../../kernel/slice.ts";
import type { CliCall } from "../domain/request.ts";
import { parseInput } from "../domain/request.ts";
import { route } from "../domain/route.ts";
import { resultText } from "../domain/text.ts";
import { toolSpec } from "../domain/tool.ts";
import {
  FALLBACK_MAX_TOKENS,
  FALLBACK_MODEL,
  FALLBACK_TIMEOUT_MS,
  JEV_TIMEOUT_MS,
} from "../limits.ts";
import { pickQuestions } from "./ask.ts";
import { type Completion, createFallback } from "./fallback.ts";
import { type CliRun, createJev } from "./jev.ts";

/** Runs the CLI `dotclaude-decide` with the key in its environment, never in the arguments. */
const runCli = async (
  $: EngineInterface,
  key: string,
  call: CliCall,
): Promise<CliRun> => {
  const run = await $.process.run(
    [
      "bun",
      "--no-env-file",
      `${$.plugin.root}/bin/dotclaude-decide`,
      ...call.args,
    ],
    {
      env: { TYPESAFE_API_KEY: key },
      timeoutMs: JEV_TIMEOUT_MS,
      ...(call.stdin === undefined ? {} : { stdin: call.stdin }),
    },
  );
  return { exitCode: run.exitCode, stdout: run.stdout, stderr: run.stderr };
};

/** One completion with the fallback model, which answers for Claude and not for Jev. */
const complete = async (
  $: EngineInterface,
  prompt: { system: string; prompt: string },
): Promise<Completion> => {
  const reply = await $.model.complete({
    model: FALLBACK_MODEL,
    system: prompt.system,
    prompt: prompt.prompt,
    maxTokens: FALLBACK_MAX_TOKENS,
    effort: "low",
    timeoutMs: FALLBACK_TIMEOUT_MS,
  });
  return reply.isAnswered
    ? { isAnswered: true, text: reply.text }
    : { isAnswered: false };
};

// A failure here reaches the log of Claude Code, and the session goes on with no tool.
export const onSessionStart: Handler<"session.start"> = async ($, e, next) => {
  await $.tool.register(toolSpec());
  return next(e);
};

export const onSecondOpinion: Handler<"tool.call"> = async ($, e) => {
  // An MCP tool gets its arguments as the fields of `e`, next to `tool` and `tool_use_id`.
  const parsed = parseInput(e);
  if (!parsed.ok) return { result: parsed.error };
  const key = await $.env.get("TYPESAFE_API_KEY");
  const jev = key ? createJev((call) => runCli($, key, call)) : undefined;
  const fallback = createFallback((prompt) => complete($, prompt));
  return { result: resultText(await route(jev, fallback, parsed.request)) };
};

/** The hook for `AskUserQuestion`, with `e` narrowed to that tool by the filter of `slice.ts`. */
export type AskHook = MatchedHook<
  "tool.call",
  { readonly tool: readonly ["AskUserQuestion"] }
>;

/** The `AskUserQuestion` call with the pick of Jev in each facts question. With no key, the call passes unchanged. */
export const onAskUserQuestion: AskHook = async ($, e, next) => {
  const key = await $.env.get("TYPESAFE_API_KEY");
  if (!key) return next(e);
  const questions = await pickQuestions(e.questions, (call) =>
    runCli($, key, call),
  );
  return next(questions === undefined ? e : { ...e, questions });
};

files.slices/guard/adapters/mod.ts:
// Generated by `just generate` from `src/plugins/dotclaude/slices/guard/adapters/mod.ts`. Edit the source and run `just generate`.
// The mod handlers of the `guard` slice:
// `tool.call` on `Bash` denies a destructive command (the floor of `domain/guard.ts`), also in a subagent's call,
// and denies a command that only prints a file and names the `Read` call (design D22),
// and `tool.check` asks before the first call of a session that reaches a GitHub repository of another owner with an AI policy.
//
// The guard only asks, and it keeps a deny of the engine, so it never weakens a rule of the user.
// The hook has no catch-all on purpose.
// When it throws after `next` resolved, Claude Code logs the failure and the verdict of the engine stands.
// When it throws before `next`, Claude Code skips the hook and the call runs.
// A `catch` here names the error that it expects, and the others reach that log.
//
// `claude plugin validate` follows `$` only into a function of one file,
// so each function that touches `$` is here, and the rules are in `domain/`.

import type { EngineInterface } from "claude-code";
import { POLICY_TIMEOUT_MS } from "../../../kernel/budget.ts";
import type { Handler } from "../../../kernel/slice.ts";
import { lineCount } from "../../../kernel/text.ts";
import { type Count, printReason } from "../domain/deny.ts";
import { guardReason } from "../domain/guard.ts";
import { isAbsPath, normPath } from "../domain/matchers/norm.ts";
import type { PathKind } from "../domain/matchers/types.ts";
import {
  askReason,
  LOGIN_ARGV,
  linesOf,
  ORGS_ARGV,
  type PolicyRead,
} from "../domain/owners.ts";
import { printsOf } from "../domain/reads.ts";
import { READ_MAX_BYTES } from "../limits.ts";

/**
 * The stdout of `argv`, or `null` when it exits with a code other than 0.
 * A run that throws is not caught: Claude Code logs it and the verdict of the engine stands.
 */
const output = async ($: EngineInterface, argv: readonly string[]) => {
  const r = await $.process.run(argv, { timeoutMs: POLICY_TIMEOUT_MS });
  return r.exitCode === 0 ? r.stdout : null;
};

// A `gh api` call that exits 1 with `HTTP 404` on stderr names a file that does not exist.
const readOf = async (
  $: EngineInterface,
  argv: readonly string[],
): Promise<PolicyRead> => {
  const r = await $.process.run(argv, { timeoutMs: POLICY_TIMEOUT_MS });
  if (r.exitCode === 0) return { status: "text", text: r.stdout };
  if (r.exitCode === 1 && r.stderr.includes("HTTP 404")) {
    return { status: "missing" };
  }
  return { status: "failed" };
};

// The logins of the user and the organizations where the user is an admin.
// Only a complete answer is kept, so a failed `gh` call is tried again at the next check.
let owners: string[] | undefined;
const ownersOf = async ($: EngineInterface) => {
  if (owners) return owners;
  const login = await output($, LOGIN_ARGV);
  const orgs = login === null ? null : await output($, ORGS_ARGV);
  const found = [...linesOf(login), ...linesOf(orgs)];
  if (login !== null && orgs !== null && linesOf(login).length) owners = found;
  return found;
};

// The repositories of each session whose policy files were read and had no text.
const checked = new Map<string, Set<string>>();

/**
 * What a path is for the matchers: `missing` for `ENOENT`, and a folder for any other file system error (fail closed).
 * A link that leads nowhere, or another kind, reads as a folder, so a matcher does not take it for a file.
 */
const kindOf =
  ($: EngineInterface) =>
  async (path: string): Promise<PathKind> => {
    try {
      const stat = await $.fs.stat(path);
      return stat.kind === "file" ? "file" : "folder";
    } catch (err) {
      return (err as { code?: string }).code === "ENOENT"
        ? "missing"
        : "folder";
    }
  };

/**
 * True when the folder `dir` (or the session folder when `dir` is unset, and a relative `dir` joins it) is in the main checkout.
 * The walk goes up to the first `.git`: a file means a linked worktree, a folder means the main checkout.
 * A `\` is read as `/`, so a Windows path walks up like a POSIX one, and the walk ends at the drive root.
 * When no `.git` is found, the folder is not in a repository, and the branch switch stays allowed.
 */
const isMainCheckout = async (
  $: EngineInterface,
  dir?: string,
): Promise<boolean> => {
  const cwd = await $.session.cwd();
  const start =
    dir === undefined || isAbsPath(dir) ? (dir ?? cwd) : `${cwd}/${dir}`;
  let at = normPath(start.replace(/\\/g, "/"));
  for (;;) {
    const kind = await kindOf($)(`${at}/.git`);
    if (kind !== "missing") return kind === "folder";
    const cut = at.lastIndexOf("/");
    if (cut < 0) return false;
    at = at.slice(0, cut);
  }
};

/** The line count of a file for the print rule: `Infinity` when it is too large to read. */
const countOf =
  ($: EngineInterface): Count =>
  async (file) => {
    if (!(await $.fs.exists(file))) return null;
    const stat = await $.fs.stat(file);
    if (stat.kind !== "file") return null;
    if (stat.size > READ_MAX_BYTES) return Infinity;
    return lineCount(await $.fs.read(file));
  };

// The destructive floor denies a `Bash` command in every session, and the shared-checkout rule denies more in a subagent (`e.agentId`).
// A `Bash` command that prints a file, also in one part of a compound command, is denied here, and the `Read` call of the same range runs instead.
// The `sembr` rewrite of the phase `rewrite` runs before this deny of the phase `check`, so the deny checks the command that would run.
// The session folder is read only for a command that prints a file, because a relative path needs it.
export const onBashCall: Handler<"tool.call"> = async ($, e, next) => {
  if (e.tool !== "Bash") return next(e);
  const floor = await guardReason(e.command, {
    kind: kindOf($),
    isMainCheckout: (dir) => isMainCheckout($, dir),
    subagent: Boolean(e.agentId),
  });
  if (floor) return { deny: floor };
  if (!printsOf(e.command, "").length) return next(e);
  const cwd = await $.session.cwd();
  const deny = await printReason(e.command, cwd, countOf($));
  return deny ? { deny } : next(e);
};

// The ask reason of `guard` comes first, then the ask reason of `next`, so the ask of another slice stays.
export const onCheck: Handler<"tool.check"> = async ($, e, next) => {
  const verdict = await next(e);
  if (verdict?.decision === "deny") return verdict;
  const session = await $.session.id();
  let seen = checked.get(session);
  if (!seen) {
    seen = new Set();
    checked.set(session, seen);
  }
  const own = await askReason(e.tool, e.input, {
    seen,
    run: (argv) => readOf($, argv),
    owners: () => ownersOf($),
  });
  if (!own) return verdict;
  const reason =
    verdict?.decision === "ask" && verdict.reason
      ? `${own}\n\n${verdict.reason}`
      : own;
  return { decision: "ask", reason };
};

files.slices/handoff/adapters/mod.ts:
// Generated by `just generate` from `src/plugins/dotclaude/slices/handoff/adapters/mod.ts`. Edit the source and run `just generate`.
// The mod handlers of the `handoff` slice. Every handler makes no model call, so `requests` is 0.
//
// `turn.step` keeps the context of each subagent.
// `tool.call` adds the report-now note to the result of a subagent that nears a bound.
// The same `tool.call` handler sets the trigger when a package goes to `done`.
// `skill.prompt` starts the handoff of `/handoff`.
// `turn.complete` runs the handoff: it checks the triggers, submits the write prompt,
// and then, on the next `turn.complete`, runs `/clear` and submits the resume prompt.
//
// The slice keeps its flow state in this module, not in `state.json` and not in the store.
//
// `claude plugin validate` follows `$` only into a function of one file.
// For this reason, each function that touches `$` is here, and the rules are in `domain/`.

import type {
  EngineInterface,
  PluginOptions,
  TurnCompleteInput,
  TurnCompleteResult,
} from "claude-code";
import type { Handler } from "../../../kernel/slice.ts";
import {
  type AgentState,
  contextTokens,
  reportNote,
} from "../domain/context.ts";
import {
  manualHint,
  REASON_LANE,
  REASON_NO_FILE,
  reasonContext,
  resumeText,
  writePrompt,
} from "../domain/text.ts";
import {
  overContext,
  parseHandover,
  phaseDoneCall,
} from "../domain/trigger.ts";
import {
  CONTEXT_PERCENT,
  HANDOFF_RETRY_MAX,
  HANDOFF_WAIT_TURNS,
  type MainHandover,
} from "../limits.ts";

/** The state of each subagent by its `agentId`. */
const agents = new Map<string, AgentState>();

/** The `userConfig` values of the plugin, which the generated `register` gives to `keepOptions`. */
let options: PluginOptions = {};

/** The reason of a trigger that fired and has no handoff yet, or undefined. */
let wanted: string | undefined;

/**
 * The handoff files that this handoff asked Claude to write, and how many turns ended since, or undefined.
 * A retry adds a path, so a file at any of these paths counts as the written handoff.
 */
let pending: { readonly files: readonly string[]; waited: number } | undefined;

/** The state of one trigger episode, which ends when no trigger is active or a handoff runs. */
type Episode = {
  /** The kinds of trigger whose `manual` hint went to the user. */
  hinted: Set<string>;
  /** The times that the write prompt went out again. */
  retries: number;
  /** Whether the handoff of this episode ended with no resume, so no handoff starts again. */
  over: boolean;
};

const newEpisode = (): Episode => ({
  hinted: new Set(),
  retries: 0,
  over: false,
});

let episode = newEpisode();

/** Keeps the `userConfig` values of the plugin for the handlers. */
export const keepOptions = (values: PluginOptions): void => {
  options = values;
};

/** Forgets the flow state. A test calls it between runs. */
export const resetState = (): void => {
  agents.clear();
  wanted = undefined;
  pending = undefined;
  episode = newEpisode();
  options = {};
};

/** Runs the CLI `bin/<name>` of this plugin and gives its status and text. */
const runBin = async (
  $: EngineInterface,
  name: string,
  args: string[],
): Promise<{ ok: boolean; text: string }> => {
  const run = await $.process.run([
    "bun",
    "--no-env-file",
    `${$.plugin.root}/bin/${name}`,
    ...args,
  ]);
  return { ok: run.exitCode === 0, text: run.stdout.trim() };
};

/** The usage of each subagent step: its context and its model. */
export const onTurnStep: Handler<"turn.step"> = async function* (_$, e, next) {
  const result = yield* next(e);
  if (e.agentId && result.usage)
    agents.set(e.agentId, {
      tokens: contextTokens(result.usage),
      model: result.usage.model,
    });
  return result;
};

/** Adds the report-now note to the result of a tool call of a subagent that nears a bound, and watches for a merge or an accept. */
export const onToolCall: Handler<"tool.call"> = async (_$, e, next) => {
  const out = await next(e);
  if (phaseDoneCall(e, out)) {
    wanted = REASON_LANE;
    if (!pending) episode = newEpisode();
  }
  const state = e.agentId ? agents.get(e.agentId) : undefined;
  if (!state || out.deny !== undefined) return out;
  const note = reportNote(state);
  return note ? { ...out, context: [...(out.context ?? []), note] } : out;
};

/** Starts the handoff of `/handoff`: names the file in the skill text and expects the file at the next `turn.complete`. */
export const onSkill: Handler<"skill.prompt"> = async ($, e, next) => {
  const out = await next(e);
  if (parseHandover(options["mainHandover"]) === "off") return out;
  const path = await runBin($, "dotclaude-handoff", ["path"]);
  if (!path.ok) return out;
  pending = { files: [path.text], waited: 0 };
  episode = newEpisode();
  return {
    ...out,
    text: `${out.text}\n\nThe handoff file is \`${path.text}\`.`,
  };
};

/**
 * Clears the session and submits the resume prompt when the newest handoff file is one of `files`.
 * Gives whether it did.
 */
const resume = async (
  $: EngineInterface,
  files: readonly string[],
): Promise<boolean> => {
  const newest = await runBin($, "dotclaude-handoff", ["newest"]);
  if (!newest.ok || !files.includes(newest.text)) return false;
  const next = await runBin($, "dotclaude-spec", ["next"]);
  await $.command.run({ command: "clear" });
  await $.prompt.submit({
    text: resumeText(newest.text, next.ok ? next.text : ""),
  });
  return true;
};

/** A trigger that fired for the main session: its kind and its reason text. */
type Trigger = { readonly kind: string; readonly reason: string };

/** The trigger that fired for the main session, or undefined. */
const triggerOf = async ($: EngineInterface): Promise<Trigger | undefined> => {
  if (wanted) return { kind: "lane", reason: wanted };
  const { context } = await $.session.usage();
  return overContext(context.percent, CONTEXT_PERCENT)
    ? { kind: "context", reason: reasonContext(context.percent ?? 0) }
    : undefined;
};

/**
 * Adds the `manual` hint of `trigger` to `out`, once for each kind of trigger in an episode.
 * The text that the chain passes down is the answer itself, which the user sees already,
 * so the hint replaces that text and does not repeat it.
 */
const withHint = (
  out: TurnCompleteResult,
  trigger: Trigger,
  answer: string,
): TurnCompleteResult => {
  if (episode.hinted.has(trigger.kind)) return out;
  episode.hinted.add(trigger.kind);
  const beneath = out.text === answer ? "" : out.text;
  const hint = manualHint(trigger.reason);
  return { ...out, text: beneath ? `${beneath}\n\n${hint}` : hint };
};

/**
 * Asks Claude to write the handoff file, at a new path, and keeps the paths of `files` as well.
 * A failed `path` call starts nothing.
 */
const startWrite = async (
  $: EngineInterface,
  files: readonly string[],
): Promise<void> => {
  const path = await runBin($, "dotclaude-handoff", ["path"]);
  if (!path.ok) return;
  pending = { files: [...files, path.text], waited: 0 };
  wanted = undefined;
  await $.prompt.submit({ text: writePrompt(path.text) });
};

/**
 * Ends a turn while a write prompt is out.
 * Only an `answer` turn can be the write turn that wrote the file.
 * A turn that ends with another reason drops the handoff, and none starts again in this episode.
 * When the file is not there after `HANDOFF_WAIT_TURNS` turns, the prompt goes out once more,
 * and then the `manual` hint goes to the user.
 */
const settle = async (
  $: EngineInterface,
  e: TurnCompleteInput,
  out: TurnCompleteResult,
  mode: MainHandover,
): Promise<TurnCompleteResult> => {
  const current = pending as NonNullable<typeof pending>;
  if (e.reason !== "answer") {
    pending = undefined;
    wanted = undefined;
    episode.over = true;
    return out;
  }
  if (await resume($, current.files)) {
    pending = undefined;
    wanted = undefined;
    episode = newEpisode();
    return out;
  }
  current.waited += 1;
  if (current.waited < HANDOFF_WAIT_TURNS) return out;
  pending = undefined;
  wanted = undefined;
  if (mode === "auto" && episode.retries < HANDOFF_RETRY_MAX) {
    episode.retries += 1;
    await startWrite($, current.files);
    return out;
  }
  episode.over = true;
  return withHint(out, { kind: "no-file", reason: REASON_NO_FILE }, e.answer);
};

/** Runs the handoff at the end of a turn of the main session. */
export const onTurnComplete: Handler<"turn.complete"> = async ($, e, next) => {
  const out = await next(e);
  if (e.agentId) {
    agents.delete(e.agentId);
    return out;
  }
  const mode = parseHandover(options["mainHandover"]);
  if (pending) return settle($, e, out, mode);
  if (mode === "off") {
    wanted = undefined;
    return out;
  }
  const trigger = await triggerOf($);
  if (!trigger) {
    episode = newEpisode();
    return out;
  }
  if (mode === "manual") {
    wanted = undefined;
    return withHint(out, trigger, e.answer);
  }
  if (episode.over) return out;
  await startWrite($, []);
  return out;
};

