// Generated by `just generate` from `src/plugins/dotclaude/slices/prompt/adapters/mod.ts`. Edit the source and run `just generate`.
// The mod handlers of the `prompt` slice:
// `prompt.compose` and `agent.spawn` for the prompt variant of the model,
// and `prompt.section`, which answers each built-in section that has a transform with its shorter text.

import type { Handler } from "../../../kernel/slice.ts";
import {
  composeSections,
  transformText,
  variantKey,
  withBlock,
} from "../domain/apply.ts";
import type { VariantKey } from "../domain/variants.ts";
import { TRANSFORMS } from "../transforms/index.ts";

// The variant key of each session, chosen at the first `prompt.compose` of the session and kept.
// A model switch changes nothing, because a changed system prompt breaks the cache.
const variants = new Map<string, VariantKey | null>();

export const onCompose: Handler<"prompt.compose"> = async ($, e, next) => {
  const result = await next(e);
  if (e.traits.includes("bare")) return result;
  const sections = result.sections.map((s) => ({
    ...s,
    text: transformText(s.id, s.text),
  }));
  const session = await $.session.id();
  if (!variants.has(session))
    variants.set(session, variantKey(e.promptModel || e.model));
  const key = variants.get(session);
  return key ? { sections: composeSections(sections, key) } : { sections };
};

// A subagent gets its system prompt from its agent body, so its model block goes to the end of the task prompt.
export const onSpawn: Handler<"agent.spawn"> = (_$, e, next) => {
  const model = e.model && e.model !== "inherit" ? e.model : e.parentModel;
  const key = variantKey(model);
  return next(key ? { ...e, prompt: withBlock(e.prompt, key) } : e);
};

// The transform of a section is the same for each call, so the cached answer keeps the prompt cache.
// The `context_management` section says that the context is summarized, so its transform applies only
// with `DISABLE_COMPACT`, where the context is not summarized.
export const onSection: Handler<"prompt.section"> = async ($, e, next) => {
  if (!TRANSFORMS.has(e.name) || e.text === null) return next(e);
  if (e.name === "context_management") {
    const off = await $.env.get("DISABLE_COMPACT");
    if (!off || off === "0" || off === "false") return next(e);
  }
  return { text: transformText(e.name, e.text) };
};

