      $.ui.log(
        `dotclaude-spec ${args.join(" ")} failed with exit status ${run.exitCode}: ${run.stderr.trim()}`,
        { to: "debug" },
      );
  } catch {
    $.ui.log(`dotclaude-spec ${args.join(" ")} did not run`, { to: "debug" });
  }
  return out;
};

