// Generated by `just generate` from `src/plugins/dotclaude/slices/stamp/adapters/mod.ts`. Edit the source and run `just generate`.
// The mod handler of the `stamp` slice: `session.start` appends the build of the session as a `system` notice (P38).
// It reads `plugin.json`, `installed_plugins.json`, and the transcript of the session, and runs `git` only when no install entry gives a SHA.
// It appends a notice only when the transcript holds no stamp yet, or its newest stamp has another build, so a resume on the same build adds no row.
// It reads each file only and never writes one, apart from the notice that `session.append` writes.
// A missing install record is the normal case of `--plugin-dir`, so it gives no SHA and `git` runs instead.
// A failed read of `plugin.json` gives no version, so the session gets no stamp.
// The hook never throws, so a stamp cannot stop a session.

import type { EngineInterface } from "claude-code";
import type { Handler } from "../../../kernel/slice.ts";
import { formatStamp, type StampRecord } from "../../../kernel/stamp.ts";
import {
  chooseSha,
  gitSha,
  gitTop,
  installedSha,
  needsStamp,
  newestStamp,
  parseJson,
  projectFolder,
  versionOf,
} from "../domain/build.ts";
import { GIT_TIMEOUT_MS } from "../limits.ts";

/** The file of Claude Code that records each installed plugin, in `CLAUDE_CONFIG_DIR` or in `~/.claude`. */
const INSTALLED_FILE = "plugins/installed_plugins.json";

/** The file that marks the top folder of a dotclaude checkout. */
const MARKETPLACE = ".claude-plugin/marketplace.json";

/**
 * The text of `file`, or undefined when the read fails.
 * The catch has no narrower test on purpose: a missing file, a folder, and a file over the bound all give no text.
 */
const readText = async (
  $: EngineInterface,
  file: string,
): Promise<string | undefined> => {
  try {
    return await $.fs.read(file);
  } catch {
    return undefined;
  }
};

/** The config folder of Claude Code: `CLAUDE_CONFIG_DIR`, else `~/.claude`, or undefined when neither is set. */
const configDir = async ($: EngineInterface): Promise<string | undefined> => {
  const configured = await $.env.get("CLAUDE_CONFIG_DIR");
  if (configured) return configured;
  const home = await $.env.get("HOME");
  return home ? `${home}/.claude` : undefined;
};

/** The path of `installed_plugins.json`, or undefined when neither `CLAUDE_CONFIG_DIR` nor `HOME` is set. */
const installedPath = async (
  $: EngineInterface,
): Promise<string | undefined> => {
  const dir = await configDir($);
  return dir === undefined ? undefined : `${dir}/${INSTALLED_FILE}`;
};

/** The path of the transcript of this session, or undefined when no config folder is set. Claude Code keeps it under `projects/`, in the folder of the working directory. */
const transcriptPath = async (
  $: EngineInterface,
  sessionId: string,
): Promise<string | undefined> => {
  const dir = await configDir($);
  if (dir === undefined) return undefined;
  const folder = projectFolder(await $.session.cwd());
  return `${dir}/projects/${folder}/${sessionId}.jsonl`;
};

/**
 * The newest stamp of the transcript of this session, or `null` when the transcript exists and its read fails.
 * A missing transcript, or no config folder, gives no stamp, so the session is new and gets one.
 * `fs.read` rejects a file over 4 MiB, so a long session has a transcript that exists and cannot be read, and no stamp is written for it.
 */
const transcriptStamp = async (
  $: EngineInterface,
  sessionId: string,
): Promise<{ newest: StampRecord | undefined } | null> => {
  const file = await transcriptPath($, sessionId);
  if (file === undefined || !(await $.fs.exists(file)))
    return { newest: undefined };
  const text = await readText($, file);
  return text === undefined ? null : { newest: newestStamp(text) };
};

/** The short SHA of this plugin in the install record, or undefined. */
const installSha = async ($: EngineInterface): Promise<string | undefined> => {
  const file = await installedPath($);
  if (file === undefined) return undefined;
  const text = await readText($, file);
  return installedSha(parseJson(text), $.plugin.root);
};

/** The output of `git rev-parse` with `args` in the plugin root, or undefined when `git` fails or is absent. */
const revParse = async (
  $: EngineInterface,
  args: string[],
): Promise<{ exitCode: number | null; stdout: string } | undefined> => {
  try {
    return await $.process.run(["git", "rev-parse", ...args], {
      cwd: $.plugin.root,
      timeoutMs: GIT_TIMEOUT_MS,
    });
  } catch {
    return undefined;
  }
};

/**
 * The short SHA that `git` gives in the plugin root, or undefined.
 * The plugin root can sit in a parent repository, so `git` gives a SHA only when the top folder
 * holds `MARKETPLACE`, the mark of a dotclaude checkout.
 */
const gitShaOf = async ($: EngineInterface): Promise<string | undefined> => {
  const top = await revParse($, ["--show-toplevel"]);
  const folder = top === undefined ? undefined : gitTop(top);
  if (folder === undefined) return undefined;
  if ((await readText($, `${folder}/${MARKETPLACE}`)) === undefined) return;
  const head = await revParse($, ["--short", "HEAD"]);
  return head === undefined ? undefined : gitSha(head);
};

/** The record of this session, or undefined when the manifest gives no version. */
const recordOf = async (
  $: EngineInterface,
): Promise<StampRecord | undefined> => {
  const manifest = parseJson(
    await readText($, `${$.plugin.root}/.claude-plugin/plugin.json`),
  );
  const version = versionOf(manifest);
  if (version === undefined) return undefined;
  // `git` runs only when the install record gives no SHA, so the common start runs no process.
  const installed = await installSha($);
  const git = installed === undefined ? await gitShaOf($) : undefined;
  return {
    version,
    ...chooseSha(installed, git),
    sessionId: await $.session.id(),
    at: new Date().toISOString(),
  };
};

/** Appends the stamp, and does nothing when a read gives no version, the transcript exists but cannot be read, or the newest stamp has the same build. */
const stamp = async ($: EngineInterface): Promise<void> => {
  const record = await recordOf($);
  if (record === undefined) return;
  const transcript = await transcriptStamp($, record.sessionId);
  if (transcript === null || !needsStamp(transcript.newest, record)) return;
  await $.session.append({
    message: {
      type: "system",
      content: [{ type: "text", text: formatStamp(record) }],
    },
  });
};

// The stamp runs after `next`, so a session starts with the same hooks as without the stamp.
export const onSessionStart: Handler<"session.start"> = async ($, e, next) => {
  const started = await next(e);
  try {
    await stamp($);
  } catch {
    // A failed append or id read writes no stamp, and the session goes on.
  }
  return started;
};

