// Generated by `just generate` from `src/plugins/dotclaude/slices/stamp/domain/build.ts`. Edit the source and run `just generate`.
// The pure rules of the session stamp: the version, the SHA, and the choice between the two sources.
// The reads of the files and the `git` call are in `adapters/mod.ts`, so this file imports no adapter.

import {
  parseStamp,
  type ShaSource,
  STAMP_PREFIX,
  type StampRecord,
  UNKNOWN_SHA,
} from "../../../kernel/stamp.ts";

/** A SHA as `git` writes it in lowercase hex, from four characters to the full forty. */
const SHA = /^[0-9a-f]{4,40}$/;

/** The short form of a SHA: its first seven characters, or undefined when `value` is not a SHA. */
export const shortSha = (value: unknown): string | undefined =>
  typeof value === "string" && SHA.test(value) ? value.slice(0, 7) : undefined;

/** The parsed JSON of `text`, or undefined when `text` is absent or not JSON. */
export const parseJson = (text: string | undefined): unknown => {
  if (text === undefined) return undefined;
  try {
    return JSON.parse(text);
  } catch {
    return undefined;
  }
};

/** The value of `key` in `value`, or undefined when `value` is not an object. */
const field = (value: unknown, key: string): unknown =>
  typeof value === "object" && value !== null
    ? (value as Record<string, unknown>)[key]
    : undefined;

/**
 * `value` with forward slashes and no trailing slash, or undefined when it is not text.
 * A Windows path can come with either separator, so both sides of a compare use this form.
 */
const trimmed = (value: unknown): string | undefined =>
  typeof value === "string"
    ? value.replaceAll("\\", "/").replace(/\/+$/, "")
    : undefined;

/** The `version` of a parsed `plugin.json`, or undefined when it has none. */
export const versionOf = (manifest: unknown): string | undefined => {
  const version = field(manifest, "version");
  return typeof version === "string" && version !== "" ? version : undefined;
};

/**
 * The short SHA of the entry whose `installPath` is `root`, from a parsed `installed_plugins.json`.
 * An entry with no SHA, and a file with no entry for `root`, give undefined.
 */
export const installedSha = (
  installed: unknown,
  root: string,
): string | undefined => {
  const plugins = field(installed, "plugins");
  if (typeof plugins !== "object" || plugins === null) return undefined;
  const entries = Object.values(plugins).flatMap((list) =>
    Array.isArray(list) ? list : [],
  );
  const shas = entries
    .filter((entry) => trimmed(field(entry, "installPath")) === trimmed(root))
    .map((entry) => shortSha(field(entry, "gitCommitSha")));
  return shas.find((sha) => sha !== undefined);
};

/** The short SHA that `git rev-parse --short HEAD` printed, or undefined when it failed or printed no SHA. */
export const gitSha = (run: {
  exitCode: number | null;
  stdout: string;
}): string | undefined =>
  run.exitCode === 0 ? shortSha(run.stdout.trim()) : undefined;

/** The top folder that `git rev-parse --show-toplevel` printed, or undefined when it failed or printed nothing. */
export const gitTop = (run: {
  exitCode: number | null;
  stdout: string;
}): string | undefined => {
  const top = run.stdout.trim();
  return run.exitCode === 0 && top !== "" ? top : undefined;
};

/** The folder of a session's transcripts for the working directory `cwd`: each character that is not a letter or a digit becomes `-`. */
export const projectFolder = (cwd: string): string =>
  cwd.replace(/[^a-zA-Z0-9]/g, "-");

/**
 * The newest stamp row of a transcript text, or undefined when it holds none.
 * Only a `system` row counts, as `dotclaude-usage` reads it, and a line that is not JSON gives nothing.
 */
export const newestStamp = (
  text: string | undefined,
): StampRecord | undefined => {
  if (text === undefined) return undefined;
  let newest: StampRecord | undefined;
  for (const line of text.split("\n")) {
    if (!line.includes(STAMP_PREFIX)) continue;
    const row = parseJson(line);
    if (field(row, "type") !== "system") continue;
    newest = parseStamp(field(row, "content")) ?? newest;
  }
  return newest;
};

/**
 * Whether a session needs a stamp row for `record`: it has no row yet, or its newest row has another version or SHA.
 * A resume on the same build therefore adds no row, and a resume on a new build adds one.
 */
export const needsStamp = (
  newest: StampRecord | undefined,
  record: Pick<StampRecord, "version" | "sha">,
): boolean =>
  newest === undefined ||
  newest.version !== record.version ||
  newest.sha !== record.sha;

/** The SHA of a stamp and its source: the install record first, then `git`, else `unknown`. */
export const chooseSha = (
  installed: string | undefined,
  git: string | undefined,
): { sha: string; shaSource: ShaSource } => {
  if (installed !== undefined) return { sha: installed, shaSource: "install" };
  if (git !== undefined) return { sha: git, shaSource: "git" };
  return { sha: UNKNOWN_SHA, shaSource: "unknown" };
};

