  CI_GITHUB_PATHS,
  CI_NAMES,
  CODE_EXTENSIONS,
  DATA_EXTENSIONS,
  HOOK_PATHS,
  LINT_CONFIG_NAMES,
  RUNNER_CONFIG_NAMES,
  RUST_IGNORE,
  SKIPPED_TEST,
  SUPPRESSION,
  SUPPRESSION_ATTRIBUTE,
  TEST_FOLDER,
  TEST_NAMES,
  TEST_SUFFIX_NAME,
