};
const WHY = "Such a change can hide a defect that a check exists to find.";

/** What a change of the kind `label` puts at risk. */
export const riskOf = (label: string): string => RISK[label] ?? WHY;

const FINDING = (
  rel: string,
  label: string,
): string => `The file \`${rel}\` is ${label}.
