 * The check skips a target under `/dev` and under a variable other than `CLAUDE_PROJECT_DIR` or `HOME`.
 */
const locate = (word: string, root: string): Located | undefined => {
  if (word.startsWith("/dev/")) return undefined;
  if (HOME_PREFIX.test(word)) {
    const rest = word.replace(HOME_PREFIX, "");
    const rel = normalize(`/home/${literalOf(rest)}`).slice(1);
    return { rel, open: literalOf(rest) !== rest, shown: word, outside: true };
  }
  const w = word.replace(PROJECT_VARIABLE, root);
  if (/^[~$`]/.test(w)) return undefined;
  const rel = resolved(w, root, false);
  const open = rel !== resolved(w, root, true);
  if (rel === ".." || rel.startsWith("../") || isAbsolute(rel))
    return {
      rel: resolve(root, literalOf(w)).slice(1),
      open,
      shown: word,
      outside: true,
    };
  return { rel, open, shown: open ? word : rel, outside: false };
};

/** The form of a path that code in another language names. */
const SCRIPT_FORM = "a script";

/** True when the write only adds to a test file or a limits file, so it gets no ask. A path-only kind always asks. */
const adds = (
  kind: string,
  mode: string | undefined,
  exists: boolean,
): boolean => {
  if (kind !== "a test file" && kind !== "a limits file") return false;
  return mode === "append" || (mode === "create" && !exists);
};

/** Whether `text` has a write word: `File.write`, `fs.rmSync`, an open mode such as `"w"`, or a redirect. A word with `/` is a path and does not count. */
const hasWriteWord = (text: string): boolean =>
  CODE_REDIRECT.test(text) ||
  codeWords(text).some((word) => {
    if (word.includes("/")) return false;
    const lower = word.toLowerCase();
    return (
      CODE_WRITE_MODES.includes(word) ||
      CODE_WRITE_PARTS.some((part) => lower.includes(part)) ||
      word.split(".").some((part) => CODE_WRITE_WORDS.includes(part))
    );
  });

/**
 * The ask reasons for the writes in `command`. A list of strings, empty when no write form has a protected target.
 * `scripts` are the texts of the script files that the command runs (`scriptTexts`).
 */
export const shellWriteReasons = async (
  command: string,
  root: string,
  read: Reader,
  scripts: Scripts,
): Promise<string[]> => {
  const { commands, redirects, code, fileCode, truncated } = withScripts(
    command,
    scripts,
  );
  // The guard cannot read a command over the scan bound, so it asks, as the git guard does.
  if (truncated)
    return [
      `The command is longer than ${SHELL_SCAN_MAX_CHARS} characters, so the write guard cannot read all of it.
It can write a protected path in the part that it does not read.
Shorter commands let the guard read each one.`,
    ];
  const found: Write[] = [
    // Code in another language can write any path that it names, with a shell command or with its own file API.
    // A path counts only when the same code has a write word. A shell command in the code is read below.
    ...code
      .filter(hasWriteWord)
      .flatMap(codeWords)
      .map((word) => ({ form: SCRIPT_FORM, word, mode: "script" })),
    ...[...code, ...fileCode].flatMap(codeCommands).flatMap(targets),
    ...redirects.map(({ op, target }) => ({
      form: op,
      word: target,
      mode: op.endsWith(">>") ? "append" : "create",
    })),
    ...commands.flatMap(targets),
  ];
  const out = new Map<string, string>();
  for (const { form, word, folders, mode, pathOnly, needsExist } of found) {
    if (word === undefined || word === "") continue;
    const at = locate(word, root);
    if (!at) continue;
    const { rel, open, shown, outside } = at;
    const only = outside || pathOnly === true;
    const kind =
      (await kindOf(rel, root, read, only)) ??
      (folders ? await kindOf(`${rel}/x`, root, read, only) : undefined);
    if (!kind) continue;
    if (needsExist && (await read(`${root}/${rel}`)) === null) continue;
    if (
      adds(
        kind,
        mode,
        folders || open ? true : (await read(`${root}/${rel}`)) !== null,
      )
    )
      continue;
    const what =
      form === SCRIPT_FORM
        ? `A script that a program other than the shell runs names the path \`${shown}\`.
The check cannot read a script in another language, so it treats each path that the script names as a write.`
        : `The command form \`${form}\` writes the path \`${shown}\`.`;
    out.set(
      `${form} ${word}`,
      `${what}
The path is ${kind}.${open ? "\nThe path has a variable or a glob, so the check reads only its literal part." : ""}
${riskOf(kind)}`,
    );
  }
  return [...out.values()].slice(0, ITEMS_SHOWN_MAX);
};

