// Generated by `just generate` from `src/kernel/paths.ts`. Edit the source and run `just generate`.
// The paths of the files that dotclaude reads or writes, in one place.
// The file has no import, so the module graph of a hooks module can use it.
// `.claude/` holds the files that Claude Code reads.
// `.dotclaude/` holds the files that dotclaude writes, with a layout based on `.claude/`.
// The list of each file is in `.dotclaude/spec/changes/1.0.0/evidence/dotclaude-directory.md`.

/** The folder of Claude Code, in a project and in the home folder. */
export const CLAUDE_DIR = ".claude";

/** The folder of dotclaude, in a project and in the home folder. */
export const DOTCLAUDE_DIR = ".dotclaude";

/** The state file of Claude Code. It sits in `CLAUDE_CONFIG_DIR`, or in the home folder. */
export const CLAUDE_STATE_FILE = ".claude.json";

/** The shared settings file, in `.claude/` and in `~/.claude/`. */
export const SETTINGS_FILE = "settings.json";

/** The local settings file of a project. Git does not track it. */
export const LOCAL_SETTINGS_FILE = "settings.local.json";

/** The path of the project settings file, from the project root. */
export const PROJECT_SETTINGS = `${CLAUDE_DIR}/${SETTINGS_FILE}`;

/** The path of the local settings file, from the project root. */
export const PROJECT_LOCAL_SETTINGS = `${CLAUDE_DIR}/${LOCAL_SETTINGS_FILE}`;

/** The folder of the hook scripts of a project or of the home folder. Claude Code runs hooks from `settings.json`, not from this folder. */
export const CLAUDE_HOOKS_DIR = `${CLAUDE_DIR}/hooks`;

/** The folder of the handoff files, from the project root. One checkout and one session own them. */
export const HANDOFF_DIR = `${DOTCLAUDE_DIR}/handoff`;

/** The last `rate_limits` of the status line, with the time they were read. The status line writes it, and `dotclaude-spec runs` reads it. Git must not track it. */
export const RATE_LIMITS_FILE = `${DOTCLAUDE_DIR}/rate-limits.jsonl`;

/** The folder of the log files of `dotclaude-run-checks`. It is a runtime folder, and git must not track it. */
export const CHECKS_DIR = `${DOTCLAUDE_DIR}/checks`;

/** The folder of the spec store in a project. The repository tracks it. */
export const SPEC_DIR = `${DOTCLAUDE_DIR}/spec`;

/** The folder that holds one folder for each change. */
export const SPEC_ROOT = `${SPEC_DIR}/changes`;

/** The folder of the finished changes. */
export const ARCHIVE_DIR = `${SPEC_ROOT}/archive`;

/** The folder of the specs, which are the truth. */
export const SPECS_DIR = `${SPEC_DIR}/specs`;

/** The scratch copy of `SPECS_DIR` during one `archive` command. */
export const SPECS_TEMP = `${SPEC_DIR}/.specs-new`;

/** The scratch folder that holds the old `SPECS_DIR` during one `archive` command. */
export const SPECS_OLD = `${SPEC_DIR}/.specs-old`;

/** The folder of the records of the hotfixes. */
export const HOTFIX_DIR = `${SPEC_DIR}/hotfixes`;

/** The runtime paths in `.claude/` that git must not track. Claude Code writes the first ones, and the last one is a local file. */
export const CLAUDE_LOCAL_PATHS = [
  "scheduled_tasks.lock",
  "scheduled_tasks.json",
  "routines/.state/",
  "worktrees/",
  "checkpoints/",
  "mailbox/",
  "agent-registry.json",
  "agent-memory-local",
  "first-run",
  "assistant-daemon-state.json",
  LOCAL_SETTINGS_FILE,
] as const;

/** The paths in `.dotclaude/` that git must not track. */
export const DOTCLAUDE_LOCAL_PATHS = [
  "handoff/",
  "checks/",
  "spec/.specs-new/",
  "spec/.specs-old/",
  "rate-limits.jsonl",
] as const;

/** The patterns for `.git/info/exclude`: only the local checkout needs them, so the team `.gitignore` stays as it is. */
export const GIT_EXCLUDE_PATTERNS: readonly string[] = [
  ...CLAUDE_LOCAL_PATHS.map((rel) => `**/${CLAUDE_DIR}/${rel}`),
  ...DOTCLAUDE_LOCAL_PATHS.map((rel) => `**/${DOTCLAUDE_DIR}/${rel}`),
];

