// Generated by `just generate` from `src/plugins/dotclaude/slices/decide/domain/picks.ts`. Edit the source and run `just generate`.
// The random order of the options of a `pick` question, and the words that the CLI takes for each option.

import type { Option } from "../ports.ts";

/** A copy of the items in a random order (Fisher-Yates). */
export const shuffled = <T>(items: readonly T[], random = Math.random): T[] => {
  const out = [...items];
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [out[i], out[j]] = [out[j] as T, out[i] as T];
  }
  return out;
};

/** Each option as one word, `key=description`, in a random order. */
export const pickWords = (
  options: readonly Option[],
  random = Math.random,
): string[] =>
  shuffled(options, random).map((o) => `${o.key}=${o.description ?? ""}`);

