    return [
      "dotclaude forbids this destructive action.",
      "Stop this work.",
      "Put this exact command in your report, so that the main session can give it to the user:",
      quoted(command),
    ].join("\n");
  return [
    "dotclaude forbids this destructive action.",
    "Do not try another way to do it.",
    "Stop this work.",
    "Ask the user to run this exact command as a `!` command, then wait for the user:",
    quoted(command),
  ].join("\n");
};

